import{_ as t,o,c as i,a3 as a}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"Attached Code Repositories","description":"Guide to attaching, indexing, and monitoring external Git repositories in Notely.","frontmatter":{"title":"Attached Code Repositories","description":"Guide to attaching, indexing, and monitoring external Git repositories in Notely.","keywords":"git, repositories, code, ast, knowledge graph, code monitoring, symbols","category":"Workspace"},"headers":[],"relativePath":"workspace/attached-repos.md","filePath":"workspace/attached-repos.md","lastUpdated":1791034783000}'),n={name:"workspace/attached-repos.md"};function r(s,e,d,l,c,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="attached-code-repositories" tabindex="-1">Attached Code Repositories <a class="header-anchor" href="#attached-code-repositories" aria-label="Permalink to &quot;Attached Code Repositories&quot;">​</a></h1><p>Notely allows you to attach external local <strong>Git repositories</strong> to your workspace. This bridges the gap between your documentation notes and your codebase, powering deep AST symbol indexing, cross-referencing, and unified Knowledge Graph queries.</p><hr><h2 id="_1-overview-capabilities" tabindex="-1">1. Overview &amp; Capabilities <a class="header-anchor" href="#_1-overview-capabilities" aria-label="Permalink to &quot;1. Overview &amp; Capabilities&quot;">​</a></h2><p>When you attach a code repository to Notely:</p><ul><li><strong>Zero Copying</strong>: Your codebase stays in its original location on disk; Notely only registers its metadata path.</li><li><strong>AST Symbol Extraction</strong>: Notely&#39;s <code>CodeKnowledgeSource</code> engine scans code files across 8+ programming languages to extract modules, classes, functions, routes, and data models.</li><li><strong>Bi-directional Knowledge Graph Links</strong>: Code symbols and modules become first-class graph entities (<code>CodeModule</code>, <code>CodeClass</code>, <code>CodeFunction</code>, <code>APIEndpoint</code>, <code>DBModel</code>) that link semantically to your architectural and design notes.</li><li><strong>Note Cross-Referencing</strong>: Mention any repository name in your notes using <code>[[RepoName]]</code> or <code>@RepoName</code> to link your notes with that codebase.</li></ul><hr><h2 id="_2-attaching-a-repository" tabindex="-1">2. Attaching a Repository <a class="header-anchor" href="#_2-attaching-a-repository" aria-label="Permalink to &quot;2. Attaching a Repository&quot;">​</a></h2><p>To attach a repository to your active workspace:</p><ol><li>Open the <strong>Attached Repositories</strong> page: <ul><li>Click the <strong>Attached Repositories</strong> button on the Landing Dashboard.</li><li>Or select <strong>Workspace → Attached Code Repositories</strong> in the top menu bar.</li><li>Or press <code>Cmd/Ctrl + K</code> and type <code>Attached Repositories</code>.</li></ul></li><li>Click <strong>Attach Repo</strong> (<code>+</code>) in the top-right toolbar.</li><li>Provide repository details: <ul><li><strong>Folder Path</strong>: Enter or browse (<code>Browse</code>) to the local Git repository directory.</li><li><strong>Display / Alias Name</strong>: (Optional) Friendly name for the repo (e.g. <code>backend-api</code>, <code>web-client</code>).</li><li><strong>Branch</strong>: (Optional) Target tracking branch (defaults to <code>main</code>).</li></ul></li><li>Click <strong>Attach Repository</strong>.</li></ol><p>Notely immediately saves the repository entry into your workspace&#39;s <code>.notes-app/metadata.json</code> file.</p><hr><h2 id="_3-code-knowledge-graph-ast-indexing" tabindex="-1">3. Code Knowledge Graph &amp; AST Indexing <a class="header-anchor" href="#_3-code-knowledge-graph-ast-indexing" aria-label="Permalink to &quot;3. Code Knowledge Graph &amp; AST Indexing&quot;">​</a></h2><p>Once attached, clicking <strong>Rescan Graph</strong> triggers Notely&#39;s offline AST parsing engine:</p><h3 id="supported-languages-file-extensions" tabindex="-1">Supported Languages &amp; File Extensions <a class="header-anchor" href="#supported-languages-file-extensions" aria-label="Permalink to &quot;Supported Languages &amp; File Extensions&quot;">​</a></h3><ul><li><strong>JavaScript &amp; TypeScript</strong>: <code>.js</code>, <code>.jsx</code>, <code>.ts</code>, <code>.tsx</code>, <code>.mjs</code>, <code>.cjs</code></li><li><strong>Python</strong>: <code>.py</code></li><li><strong>Go</strong>: <code>.go</code></li><li><strong>Rust</strong>: <code>.rs</code></li><li><strong>Java</strong>: <code>.java</code></li><li><strong>C &amp; C++</strong>: <code>.c</code>, <code>.cpp</code>, <code>.h</code>, <code>.hpp</code></li><li><strong>C#</strong>: <code>.cs</code></li><li><strong>Ruby &amp; PHP</strong>: <code>.rb</code>, <code>.php</code></li><li><strong>Frontend Components</strong>: <code>.vue</code>, <code>.svelte</code></li></ul><h3 id="extracted-entities-relationships" tabindex="-1">Extracted Entities &amp; Relationships <a class="header-anchor" href="#extracted-entities-relationships" aria-label="Permalink to &quot;Extracted Entities &amp; Relationships&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Entity Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CodeModule</code></td><td style="text-align:left;">Code file/module representation within the repository structure</td></tr><tr><td style="text-align:left;"><code>CodeClass</code></td><td style="text-align:left;">Declared classes, struct definitions, and class inheritances</td></tr><tr><td style="text-align:left;"><code>CodeInterface</code></td><td style="text-align:left;">TypeScript interfaces and type definitions</td></tr><tr><td style="text-align:left;"><code>CodeFunction</code></td><td style="text-align:left;">Exported functions, arrow functions, and method definitions</td></tr><tr><td style="text-align:left;"><code>APIEndpoint</code></td><td style="text-align:left;">HTTP routes (e.g. <code>GET /api/v1/users</code>, <code>POST /login</code>)</td></tr><tr><td style="text-align:left;"><code>DBModel</code></td><td style="text-align:left;">Schema definitions and database models</td></tr></tbody></table><p>The graph automatically constructs <code>CONTAINS</code>, <code>IMPORTS</code>, and <code>DOCUMENTS</code> relationships, allowing you to explore your system architecture interactively in the <strong>Knowledge Graph</strong> view (<code>ai-graph</code>).</p><hr><h2 id="_4-monitoring-inspector-drawer" tabindex="-1">4. Monitoring &amp; Inspector Drawer <a class="header-anchor" href="#_4-monitoring-inspector-drawer" aria-label="Permalink to &quot;4. Monitoring &amp; Inspector Drawer&quot;">​</a></h2><p>Selecting any attached repository opens the <strong>Inspector Drawer</strong> on the right side:</p><ul><li><strong>Local Path &amp; Commit Hash</strong>: Displays the full directory path, tracking branch, and recent HEAD commit hash.</li><li><strong>Referenced Notes</strong>: Automatically queries all markdown documents in the workspace and lists notes mentioning the repository (<code>[[RepoName]]</code>), complete with 1-click note navigation.</li><li><strong>Copy WikiLink (<code>[[Name]]</code>)</strong>: Copies the formatted wikilink tag to your clipboard for quick pasting into markdown notes.</li><li><strong>Open in VS Code</strong>: Direct <code>vscode://file/...</code> protocol integration to open the selected repository in VS Code immediately.</li><li><strong>Reveal in File Explorer</strong>: Opens the repository root folder in the native operating system file manager.</li></ul><hr><h2 id="_5-knowledge-graph-visualization" tabindex="-1">5. Knowledge Graph Visualization <a class="header-anchor" href="#_5-knowledge-graph-visualization" aria-label="Permalink to &quot;5. Knowledge Graph Visualization&quot;">​</a></h2><p>In the <strong>Knowledge Graph</strong> (<code>Workspace → Knowledge Graph</code> or <code>Cmd/Ctrl + G</code>), code entities from attached repositories appear with distinct visual badges and colors:</p><ul><li><strong>Purple</strong>: Classes (<code>CodeClass</code>) and Interfaces (<code>CodeInterface</code>)</li><li><strong>Sky Blue</strong>: Functions (<code>CodeFunction</code>) and Exports</li><li><strong>Indigo</strong>: Modules (<code>CodeModule</code>) and Import chains</li><li><strong>Amber</strong>: API Endpoints (<code>APIEndpoint</code>)</li><li><strong>Emerald Green</strong>: Data Models (<code>DBModel</code>)</li></ul><p>Clicking any code node highlights its incoming and outgoing dependencies, enabling architecture verification directly within your note-taking environment.</p>',28)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
